<?php declare(strict_types=1);namespace App\Modules\ContractBoq\Validators;use App\Core\Exceptions\ValidationException;use App\Core\Validation\Validator;use App\Modules\ContractBoq\DTOs\BoqSectionData;final class BoqSectionValidator{public function __construct(private readonly Validator $v){}public function validate(array $i):BoqSectionData{if(!$this->v->validate($i,['section_code'=>'required|string|max:30','title'=>'required|string|max:190','description'=>'string|max:5000']))throw new ValidationException($this->v->errors());$sort=filter_var($i['sort_order']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($sort===false)throw new ValidationException(['sort_order'=>['الترتيب يجب أن يكون رقمًا موجبًا.']]);$master=$this->id($i['work_section_id']??null);return new BoqSectionData($master,trim((string)$i['section_code']),trim((string)$i['title']),$this->n($i['description']??null),(int)$sort);}private function id(mixed $v):?int{if(trim((string)$v)==='')return null;$x=filter_var($v,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);if($x===false)throw new ValidationException(['work_section_id'=>['قسم الأعمال غير صالح.']]);return $x;}private function n(mixed $v):?string{$v=trim((string)$v);return $v===''?null:$v;}}
